@@ -265,7 +265,7 @@ message ExecuteTrajectoryRequestFlattenedOneOf {
         [(openapi.v3.property) = { description: "List of outputs should be set." }];
     wb.rae.v2.types.StartOnIO start_on_io = 9
         [(openapi.v3.property) = { description: "The execution of the trajectory will only start when this I/O action is triggered." }];
-    wb.rae.v2.types.PauseOnIO pause_on_io = 10
+    wb.rae.v2.types.PauseOnIOWithAutoResume pause_on_io = 10
         [(openapi.v3.property) = { description: "The execution of the trajectory will pause when this I/O action is triggered." }];

