diff --git a/api/proto/wb/rae/v2/types/io.proto b/api/proto/wb/rae/v2/types/io.proto
index 0f30351d4..8fc7eb2b8 100644
--- a/api/proto/wb/rae/v2/types/io.proto
+++ b/api/proto/wb/rae/v2/types/io.proto
@@ -110,3 +110,24 @@ message PauseOnIO {
     IOOrigin io_origin = 3
         [(openapi.v3.property) = { description: "States the source of the signal." }];
 }
+
+message PauseOnIOWithAutoResume {
+    option (openapi.v3.schema) = {
+        description: "Define an IO that triggers pausing of a motion."
+        required: "io"
+        required: "comparator"
+    };
+
+    wb.rae.v2.types.IOValue io = 1
+        [(openapi.v3.property) = { description: "I/O ID and I/O value that should pause the motion." }];
+
+    wb.rae.v2.types.Comparator comparator = 2
+        [(openapi.v3.property) = { description: "Used for comparison of measured value with requested value.\n"
+                                                "For example, COMPARATOR_GREATER_EQUAL does: measured value >= requested value." }];
+
+    IOOrigin io_origin = 3
+        [(openapi.v3.property) = { description: "States the source of the signal." }];
+
+    bool auto_resume = 4
+        [(openapi.v3.property) = { description: "If set, the execution is resumed once the condition is not satisfied anymore." }];
+}
