    18	      class DisconnectListener : public control::RobotModeChangeListener {
    19	      public:
    20	         using Ptr = std::unique_ptr<DisconnectListener>;
    21	
    22	         /**
    23	          * @brief Creates a ModeChangeListener which calls the given function on mode change.
    24	          *
    25	          * @param unregister The function to call on destruction of listener.
    26	          */
    27	         DisconnectListener(std::function<void(DisconnectListener*)> unregister,
    28	                            ResponseWriter<data::ExecuteTrajectoryResponse> responseWriter)
    29	               : unregister_(std::move(unregister))
    30	               , responseWriter_(std::move(responseWriter)) {
    31	         }
    32	
    33	         ~DisconnectListener() override {
    34	            unregister_(this);
    35	         }
