    37	         void modeChanged(const mode::RobotMode& mode, bool /* byClientRequested */, const std::string& reason) override {
    38	            if (mode != mode::RobotMode::ROBOT_MODE_CONTROL) {
    39	               responseWriter_(data::Error{ fmt::format("Robot is not in control mode anymore: '{}'", reason) });
    40	            }
    41	         }
    42	
    43	      private:
    44	         std::function<void(DisconnectListener*)> unregister_;
    45	         ResponseWriter<data::ExecuteTrajectoryResponse> responseWriter_;
    46	      };
