    48	      class ErrorHandler : public control::ThreadsafeExceptionQueue {
    49	      public:
    50	         using Ptr = std::shared_ptr<ErrorHandler>;
    51	
    52	         ErrorHandler(ResponseWriter<data::ExecuteTrajectoryResponse> responseWriter)
    53	               : responseWriter_(std::move(responseWriter)) {
    54	         }
    55	
    56	         void push(std::exception_ptr exception) override {
    57	            responseWriter_(data::Error{ wbr::exception::what(exception) });
    58	            control::ThreadsafeExceptionQueue::push(exception);
    59	         }
    60	
    61	         [[nodiscard]] bool hasError() const {
    62	            return control::ThreadsafeExceptionQueue::hasException();
    63	         }
    64	
    65	         [[nodiscard]] std::optional<std::string> popError() {
    66	            const auto error = control::ThreadsafeExceptionQueue::pop();
    67	            return nullptr != error ? std::make_optional(wbr::exception::what(error)) : std::nullopt;
    68	         }
    69	
    70	      private:
    71	         ResponseWriter<data::ExecuteTrajectoryResponse> responseWriter_;
    72	      };
