    74	      class ControlContext {
    75	      public:
    76	         ControlContext(control::UniqueControllerModeToken controlModeToken,
    77	                        DisconnectListener::Ptr looseControlListener,
    78	                        ErrorHandler::Ptr errorHandler,
    79	                        control::MotionGroupDevicePtr motionGroup,
    80	                        TrajectoryExecutor::Ptr trajectoryExecutor)
    81	               : motionGroup(std::move(motionGroup))
    82	               , trajectoryExecutor{ std::move(trajectoryExecutor) }
    83	               , raii_{ std::move(controlModeToken), std::move(looseControlListener), std::move(errorHandler) } {
    84	         }
    85	
    86	         control::MotionGroupDevicePtr motionGroup;
    87	
    88	         // optional, because it is not set in initializeMovement it is created only in startMovement
    89	         TrajectoryExecutor::Ptr trajectoryExecutor;
    90	
    91	         [[nodiscard]] bool hasError() const {
    92	            return raii_.errorHandler->hasError();
    93	         }
    94	
    95	         [[nodiscard]] std::optional<std::string> popError() {
    96	            return raii_.errorHandler->popError();
    97	         }
    98	
    99	      private:
   100	         // RAII for managing control mode and listeners
   101	         struct {
   102	            control::UniqueControllerModeToken controlModeToken;
   103	            DisconnectListener::Ptr looseControlListener;
   104	            ErrorHandler::Ptr errorHandler;
   105	
   106	         } raii_;
   107	      };
