   109	      std::optional<ControlContext> initializeMovement(const data::InitializeMovementRequest& request,
   110	                                                       const TrajectoryResolver& resolveTrajectory,
   111	                                                       const ResponseWriter<data::ExecuteTrajectoryResponse>& responseWriter,
   112	                                                       const ConnectionCancelledCallback& userCancelled) {
   113	         auto [trajectory, motionGroup, error] = resolveTrajectory(request.trajectory);
   114	
   115	         if (trajectory == nullptr) {
   116	            responseWriter(data::initFailed(error));
   117	            return std::nullopt;
   118	         }
   119	
   120	         auto controlModeToken = std::invoke([&motionGroup, &responseWriter, &userCancelled]() -> control::UniqueControllerModeToken {
   121	            try {
   122	               return motionGroup->claimControl("ExecuteTrajectory", userCancelled);
   123	            }
   124	            catch (const std::exception& e) {
   125	               auto error = data::AddTrajectoryError{ fmt::format("Failed to claim control: '{}'", e.what()), NAN, data::onlyErrorMessage };
   126	               responseWriter(data::initFailed(error));
   127	               return nullptr;
   128	            }
   129	            catch (...) {
   130	               auto error = data::AddTrajectoryError{ "Failed to claim control due to unknown error.", NAN, data::onlyErrorMessage };
   131	               responseWriter(data::initFailed(error));
   132	               return nullptr;
   133	            }
   134	         });
   135	
   136	         if (nullptr == controlModeToken) {
   137	            return std::nullopt;
   138	         }
   139	
   140	         try {
   141	            motionGroup->waitForStandstill();
   142	         }
   143	         catch (const std::exception& e) {
   144	            auto error = data::AddTrajectoryError{ "A movement is already ongoing. Please stop it before initializing a new one.",
   145	                                                   NAN,
   146	                                                   data::onlyErrorMessage };
   147	            responseWriter(data::initFailed(error));
   148	            return std::nullopt;
   149	         }
   150	
   151	         // Informs client in case of disconnection
   152	         auto disconnectListener =
   153	            std::make_unique<DisconnectListener>([controller = motionGroup->getControllerDevice()](
   154	                                                    DisconnectListener* listener) { controller->unregisterModeChangeListener(listener); },
   155	                                                 responseWriter);
   156	
   157	         motionGroup->getControllerDevice()->registerModeChangeListener(disconnectListener.get());
   158	
   159	         // listen to errors in control loop before starting to interacting with it
   160	         auto errorHandler = std::make_shared<ErrorHandler>(responseWriter);
   161	         motionGroup->registerErrorListener(errorHandler);
   162	
   163	         wb::robotModel::KinematicSetup kinematicSetup{
   164	            .kinematicModel = motionGroup->getKinematicModel(),
   165	            .tcpOffset = trajectory->tcp ? std::make_optional(wb::hal::tcp::toPose(*trajectory->tcp)) : std::nullopt,
   166	            .mounting = motionGroup->getMounting(),
   167	         };
   168	
   169	         const auto& jointTrajectory = trajectory->planResult.jointTrajectory;
   170	         auto player = TrajectoryExecutor::makePlayer(kinematicSetup,
   171	                                                      motionGroup->getPlanningLimits(),
   172	                                                      jointTrajectory,
   173	                                                      request.initialLocation,
   174	                                                      motionGroup->getDeviceState()->physical.jointPosition,
   175	                                                      trajectory->id,
   176	                                                      request.ignoreControllerLimits);
   177	
   178	         return wbr::util::visit(
   179	            player,
   180	            [&](const std::string& error) -> std::optional<ControlContext> {
   181	               responseWriter(data::initFailed(data::AddTrajectoryError{ error, request.initialLocation, data::onlyErrorMessage }));
   182	               return std::nullopt;
   183	            },
   184	            [&](const TrajectoryExecutor::TrajectoryPlayer& player) -> std::optional<ControlContext> {
   185	               responseWriter(data::initSuccess(error));
   186	
   187	               IOActionPlayer ioActionPlayer(motionGroup->getControllerDevice()->getBusIOClient(), trajectory->id, request.initialLocation);
   188	
   189	               auto trajectoryExecutor = std::make_shared<TrajectoryExecutor>(trajectory->id,
   190	                                                                              player,
   191	                                                                              std::move(ioActionPlayer),
   192	                                                                              motionGroup->getControllerStepRate());
   193	
   194	               motionGroup->startMotionExecution(trajectoryExecutor, trajectory->tcp);
   195	
   196	               return ControlContext{
   197	                  std::move(controlModeToken), std::move(disconnectListener), std::move(errorHandler), motionGroup, trajectoryExecutor
   198	               };
   199	            });
   200	      }
   201	
   202	      void startMovement(data::StartMovementRequest request,
   203	                         TrajectoryExecutor::Ptr trajectoryExecutor,
   204	                         const ResponseWriter<data::ExecuteTrajectoryResponse>& responseWriter,
   205	                         control::MotionGroupDevicePtr motionGroup) {
   206	         auto convertToIORequest = [&](const wbr::robot::io::IOActionRequest& ioActions) -> IORequest {
   207	            const auto busIOIds = io::getIOIds(ioActions, io::IOOrigin::BUS_IO);
   208	            if (!busIOIds.empty()) {
   209	               auto client = motionGroup->getControllerDevice()->getBusIOClient();
   210	               client->hasIOs(busIOIds);
   211	            }
   212	
   213	            return { .actions = ioActions,
   214	                     .subscription = motionGroup->getControllerDevice()->subscribeIOs(io::getIOIds(ioActions, io::IOOrigin::CONTROLLER)) };
   215	         };
   216	
   217	         trajectoryExecutor->setTarget(
   218	            TrajectoryTarget{ .target = request.target, .ioRequest = request.ioActions.transform(convertToIORequest) });
   219	
   220	         logInfo("Motion started.");
   221	
   222	         responseWriter(data::StartMovementResponse{});
   223	      }
   224	
   225	      void pauseMovement(const TrajectoryExecutor::Ptr& motionProvider,
   226	                         const ResponseWriter<data::ExecuteTrajectoryResponse>& responseWriter) {
   227	         motionProvider->pause();
   228	         responseWriter(data::PauseMovementResponse{});
   229	      }
   230	
   231	      void setPlaybackspeed(const data::PlaybackSpeedRequest& request,
   232	                            const TrajectoryExecutor::Ptr& motionProvider,
   233	                            const ResponseWriter<data::ExecuteTrajectoryResponse>& responseWriter) {
   234	         if ((request.playbackSpeedPercentage < 1) || (request.playbackSpeedPercentage > 100)) {
   235	            responseWriter(
   236	               data::PlaybackSpeedResponse{ fmt::format("Playback speed out of range: '{}%'. Playback speed must be in range [1%, 100%].",
   237	                                                        request.playbackSpeedPercentage) });
   238	            return;
   239	         }
   240	
   241	         motionProvider->setVelocityOverride(request.playbackSpeedPercentage);
   242	
   243	         responseWriter(data::PlaybackSpeedResponse{});
   244	      }
   245	   }
   246	
   247	   void executeTrajectory(const TrajectoryResolver& motionGetter,
   248	                          const MovementRequestReader& requestReader,
   249	                          const ResponseWriter<data::ExecuteTrajectoryResponse>& responseWriter,
   250	                          const ConnectionCancelledCallback& userCancelled) {
   251	      using namespace wbr::robot::motion::impl;
   252	
   253	      std::optional<ControlContext> context;
   254	      try {
   255	         while (!userCancelled()) {
   256	            auto request = requestReader();
   257	
   258	            if (!request.has_value()) {
   259	               break;
   260	            }
   261	
   262	            if (context && context->hasError()) {
   263	               responseWriter(data::Error{
   264	                  fmt::format("Error! '{}' This connection is being uninitialized. You can try to reinitialize the connection.",
   265	                              *context->popError()) });
   266	               context.reset();
   267	            }
   268	
   269	            if (!context && !std::holds_alternative<data::InitializeMovementRequest>(request.value())) {
   270	               const auto errorMessage = "This connection has not been initialized yet. Send an InitializeMovementRequest first.";
   271	               util::visit(
   272	                  request.value(),
   273	                  [&](const data::StartMovementRequest& /* ignore */) { responseWriter(data::StartMovementResponse{ errorMessage }); },
   274	                  [&](const data::PauseMovementRequest& /* ignore */) { responseWriter(data::PauseMovementResponse{ errorMessage }); },
   275	                  [&](const data::PlaybackSpeedRequest& /* ignore */) { responseWriter(data::PlaybackSpeedResponse{ errorMessage }); },
   276	                  [&](const data::InitializeMovementRequest& /* unreachable */) {});
   277	               continue;
   278	            }
   279	
   280	            util::visit(
   281	               request.value(),
   282	               [&](const data::InitializeMovementRequest& request) {
   283	                  // Trigger reset of all tokens etc.
   284	                  context.reset();
   285	
   286	                  context = initializeMovement(request, motionGetter, responseWriter, userCancelled);
   287	               },
   288	               [&](const data::StartMovementRequest& request) {
   289	                  startMovement(request, context->trajectoryExecutor, responseWriter, context->motionGroup);
   290	               },
   291	               [&](const data::PauseMovementRequest& /* empty */) { pauseMovement(context->trajectoryExecutor, responseWriter); },
   292	               [&](const data::PlaybackSpeedRequest& request) { setPlaybackspeed(request, context->trajectoryExecutor, responseWriter); });
   293	         }
   294	      }
   295	      catch (std::exception const& e) {
   296	         responseWriter(e.what());
   297	      }
   298	      catch (...) {
   299	         responseWriter("Aborted execute trajectory due to unknown error.");
   300	      }
   301	
   302	      if (context.has_value() && nullptr != context.value().trajectoryExecutor) {
   303	         context.value().trajectoryExecutor->stop();
   304	      }
   305	   }
   306	}
