     6	namespace wbr::robot::motion::impl {
     7	
     8	   io::IOActionRequest filterOnTrajectory(io::IOActionRequest ioActions,
     9	                                          double startLocation,
    10	                                          std::variant<wb::plan::player::PlayerDirection, double> target) {
    11	      using enum wb::plan::player::PlayerDirection;
    12	
    13	      const auto direction = getDirection(startLocation, target);
    14	
    15	      if (!ioActions.setIOs.empty()) {
    16	         // filter out ioActions that occur before start location relative to the direction
    17	
    18	         auto setIOs = io::SetIOList{};
    19	         setIOs.reserve(ioActions.setIOs.size());
    20	
    21	         std::erase_if(ioActions.setIOs, [&](const io::SetIO& setAction) {
    22	            switch (direction) {
    23	               case FORWARD: {
    24	                  return setAction.location < startLocation;
    25	               }
    26	               case BACKWARD: {
    27	                  return setAction.location > startLocation;
    28	               }
    29	            }
    30	
    31	            throw wb::exception::UnsupportedException("Unsupported MoveDirection");
    32	         });
    33	      }
    34	      return ioActions;
    35	   }
    36	
    37	}

