   255	         while (!userCancelled()) {
   256	            auto request = requestReader();
   257	
   258	            if (!request.has_value()) {
   259	               break;
   260	            }
   261	
   262	            if (context && context->hasError()) {
   263	               responseWriter(data::Error{
   264	                  fmt::format("Error! '{}' This connection is being uninitialized. You can try to reinitialize the connection.",
   265	                              *context->popError()) });
