   wb::hal::io::IOValue BusIOClient::getIOValue(const std::string& ioId) {
      wb::hal::io::IOValueList ioValues;
      {
         std::lock_guard<std::mutex> lock(mutex_);
         ioValues = ioValues_;
      }

      if (ioValues.empty()) {
         throw wb::exception::NotFoundException("I/O with ID '{}' not found", ioId);
      }
      auto ioValue = std::ranges::find_if(ioValues, [&](const auto& p) { return p.id == ioId; });

      if (ioValue != ioValues.end()) {
         return ioValue->value;
      }

      throw wb::exception::NotFoundException("I/O with ID '{}' not found", ioId);
   }

