    22	   state::StateCommand MotionPointGenerator::step(const state::MotionGroupDeviceState& mgState) {
    23	      // check if a new motion provider was set
    24	      changeProvider();
    25	
    26	      if (motionProvider_ != nullptr) {
    27	         state::StateCommand command = motionProvider_->step(mgState);
    28	
    29	         bool providerDone = wbr::util::visit(
    30	            command.motionCommand.executionDetails,
    31	            [](const state::Standstill&) { return true; },
    32	            [](const state::trajectory::Details& trajectoryDetails) {
    33	               return (trajectoryDetails.executionState == state::trajectory::ExecutionState::STOPPED);
    34	            },
    35	            [](const state::jogging::Details& joggingDetails) {
    36	               return std::holds_alternative<state::jogging::Stopped>(joggingDetails.executionState);
    37	            },
    38	            [](const state::action_chunks::Details& actionChunksDetails) {
    39	               return std::holds_alternative<state::action_chunks::Stopped>(actionChunksDetails.executionState);
    40	            });
