    42	         if (!providerDone) {
    43	            return command;
    44	         }
    45	
    46	         motionProvider_.reset();
    47	         tcp_.reset();
    48	         isNewMotionProviderSet_ = false;
    49	         rampdownSteps_ = 0;
    50	         isRampingDown_ = true;
    51	
    52	         standStillCommand_ = command;
    53	         logInfo("starting to command standstill at joint position '{}'", standStillCommand_->motionCommand.jointPosition.string(10));
