   200	   StateObserver ControllerRunnable::getStateObserver() {
   201	      if (isStopRequested()) {
   202	         throw wbr::exception::InternalErrorException("Cannot create state observer when ControllerRunnable is stopped or stopping");
   203	      }
   204	
   205	      std::lock_guard lock(stateNotifiersMutex_);
   206	
   207	      auto notifiers = stateNotifiers_.get();
   208	
   209	      std::erase_if(notifiers, [](const StateNotifier& notifier) { return !notifier.isObserved(); });
   210	
   211	      StateObserver newObserver(wandelController_.isVirtualRobot());
   212	      notifiers.push_back(newObserver.getNotifier());
   213	
   214	      stateNotifiers_.set(std::move(notifiers));
   215	
   216	      return newObserver;
   217	   }
