   260	      // this while loop is running as long as the controller is connected
   261	      // the purpose of this while loop is:
   262	      //  - guarantee that we act according to the selected mode (handled by executeControllerEngine)
   263	      //  - if an exception happens during the interaction with the controller/motion group
   264	      //       - catch the exception and try to run again (maybe in a lower controlmode)
   265	      //       - so that at least data from the controller is retreived and propagated to the user
   266	      while (wandelController_.isConnected() && !isStopRequested() && !controllerIORunnable_->isStopRequested()) {
   267	         exceptionPtr_ = nullptr;
   268	         removeExpiredErrorListeners();
   269	         try {
   270	            executeControllerEngine();
   271	         }
   272	
   273	         catch (wb::exception::CommunicationException& e) {
   274	            auto addedWbrTag = wb::exception::CommunicationException("controller disconnect detected: '{}'", e.what());
   275	            notifyAboutException(addedWbrTag);
   276	            break;
   277	         }
   278	         catch (wb::exception::SafetyChecksumException& e) {
   279	            notifyAboutException(e);
   280	            break;
   281	         }
   282	         catch (wbr::exception::ControllerVelocityOverrideErrorException& e) {
   283	            notifyAboutException(e);
   284	            notifyStateObservers(true);
   285	            mode_ = ControlMode::MONITOR;
   286	            stopPositionControl();
   287	         }
   288	         catch (wbr::exception::MovementAbortedException& e) {
   289	            notifyAboutException(e);
   290	            stopPositionControl();
   291	            // todo: stop runnable?
   292	         }
   293	         catch (wbr::exception::NotInExpectedModeException& e) {
   294	            notifyAboutException(e);
   295	            mode_ = ControlMode::MONITOR;
   296	            stopPositionControl();
   297	         }
   298	         catch (std::exception& e) {
   299	            // typeid is usable, as std::exception is an abstract class due to the virtual function what().
   300	            // It is a hint for missing catch-clauses.
   301	            auto asWbrException = wbr::exception::InternalErrorException(
   302	               "'{}' exception with error message '{}' occured during engine execution!", typeid(e).name(), e.what());
   303	            notifyAboutException(asWbrException);
   304	            if (ControlMode::MONITOR != mode_) {
   305	               mode_ = ControlMode::MONITOR;
   306	               stopPositionControl();
   307	            }
   308	         }
   309	         catch (...) {
   310	            auto unknownError = wbr::exception::InternalErrorException(
   311	               "unknown error of non-exception type occured during engine execution!");
   312	            notifyAboutException(unknownError);
   313	            if (ControlMode::MONITOR != mode_) {
   314	               mode_ = ControlMode::MONITOR;
   315	               stopPositionControl();
   316	            }
   317	         }
   318	      }
   319	      Runnable::requestStop();
   320	
   321	      if (controllerIORunnable_) {
   322	         controllerIORunnable_->requestStop();
   323	      }
   324	
   325	      stopAllMovements();
   326	      stopPositionControl();
   327	      disconnect();
   328	      // notify about mode change of controller to ensure all clients are informed about latest status
   329	      notifyModeChange();
   330	
   331	      notifyStateObservers(true);
   332	
   333	      if (exceptionPtr_) {
   334	         // todo?: where does this rethrow go? Does is trigger the unhandled exception handler within the runnable thread?
   335	         std::rethrow_exception(exceptionPtr_);
   336	      }
   337	      LOGGABLE_DEBUG("end controller communication");
   338	   }
